cd /app/R/sources; python3 - <<'EOF'
import json,glob,os,collections
for src in sorted(os.listdir('.')):
    files=glob.glob(f'{src}/**/*.json',recursive=True)
    sizes=sorted(os.path.getsize(f) for f in files)
    keys=collections.Counter()
    for f in files:
        try: d=json.load(open(f))
        except Exception as e: print('bad',f,e); continue
        if isinstance(d,dict): keys.update(d.keys())
        else: keys.update(['<'+type(d).__name__+'>'])
    print(src,len(files),'median',sizes[len(sizes)//2],'max',sizes[-1])
    print('  ',dict(keys.most_common(25)))
    nonjson=[f for f in glob.glob(f'{src}/**/*',recursive=True) if os.path.isfile(f) and not f.endswith('.json')]
    if nonjson: print('  nonjson',nonjson[:5],len(nonjson))
EOF

